// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.0;

interface IEntropy {
    function requestWithCallback(
        address provider,
        bytes32 userCommitment
    ) external payable returns (uint64 sequenceNumber);

    function getDefaultProvider() external view returns (address);

    function getFee(address provider) external view returns (uint128);
}

interface IEntropyConsumer {
    function entropyCallback(
        uint64 sequenceNumber,
        address provider,
        bytes32 randomNumber
    ) external;
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "./IEntropy.sol";

contract CoinFlip is IEntropyConsumer {
    IEntropy public entropy;
    address public entropyProvider;

    struct Flip {
        address player;
        uint256 betAmount;
        bool choice; // true = heads, false = tails
        bool fulfilled;
        bool won;
    }

    mapping(uint64 => Flip) public flips;
    mapping(address => uint256) public playerWins;
    mapping(address => uint256) public playerLosses;

    event FlipRequested(address indexed player, uint64 indexed sequenceNumber, uint256 betAmount, bool choice);
    event FlipResult(address indexed player, uint64 indexed sequenceNumber, bool result, bool won, uint256 payout);

    constructor(address _entropy) {
        entropy = IEntropy(_entropy);
        entropyProvider = entropy.getDefaultProvider();
    }

    function flipCoin(bool choice, bytes32 userCommitment) external payable {
        require(msg.value > 0, "Must bet something");
        require(address(this).balance >= msg.value * 2, "Insufficient contract balance");

        uint128 fee = entropy.getFee(entropyProvider);
        require(msg.value > fee, "Bet must be larger than entropy fee");

        uint64 sequenceNumber = entropy.requestWithCallback{value: fee}(
            entropyProvider,
            userCommitment
        );

        flips[sequenceNumber] = Flip({
            player: msg.sender,
            betAmount: msg.value - fee,
            choice: choice,
            fulfilled: false,
            won: false
        });

        emit FlipRequested(msg.sender, sequenceNumber, msg.value - fee, choice);
    }

    function entropyCallback(
        uint64 sequenceNumber,
        address provider,
        bytes32 randomNumber
    ) external override {
        require(msg.sender == address(entropy), "Only entropy contract can call");
        require(provider == entropyProvider, "Invalid provider");

        Flip storage flip = flips[sequenceNumber];
        require(!flip.fulfilled, "Already fulfilled");
        require(flip.player != address(0), "Invalid flip");

        // Convert random number to coin flip result (true = heads, false = tails)
        bool result = uint256(randomNumber) % 2 == 1;

        flip.fulfilled = true;
        flip.won = (flip.choice == result);

        uint256 payout = 0;
        if (flip.won) {
            payout = flip.betAmount * 2;
            payable(flip.player).transfer(payout);
            playerWins[flip.player]++;
        } else {
            playerLosses[flip.player]++;
        }

        emit FlipResult(flip.player, sequenceNumber, result, flip.won, payout);
    }

    function getPlayerStats(address player) external view returns (uint256 wins, uint256 losses) {
        return (playerWins[player], playerLosses[player]);
    }

    function getContractBalance() external view returns (uint256) {
        return address(this).balance;
    }

    function getEntropyFee() external view returns (uint128) {
        return entropy.getFee(entropyProvider);
    }

    // Owner can fund the contract for payouts
    receive() external payable {}

    // Emergency withdraw (only for testing)
    function emergencyWithdraw() external {
        require(msg.sender == address(0x742d35Cc6634C0532925a3b8D6Ac6cC85E4321C8), "Not authorized"); // Replace with your address
        payable(msg.sender).transfer(address(this).balance);
    }
}

import { useState, useEffect } from 'react'
import { ethers } from 'ethers'
import './App.css'

// Contract ABI - we'll update this after deployment
const COIN_FLIP_ABI = [
  "function flipCoin(bool choice, bytes32 userCommitment) external payable",
  "function getPlayerStats(address player) external view returns (uint256 wins, uint256 losses)",
  "function getContractBalance() external view returns (uint256)",
  "function getEntropyFee() external view returns (uint128)",
  "event FlipRequested(address indexed player, uint64 indexed sequenceNumber, uint256 betAmount, bool choice)",
  "event FlipResult(address indexed player, uint64 indexed sequenceNumber, bool result, bool won, uint256 payout)"
]

// We'll update this after contract deployment
const CONTRACT_ADDRESS = "0x0000000000000000000000000000000000000000" // Placeholder

function App() {
  const [provider, setProvider] = useState(null)
  const [signer, setSigner] = useState(null)
  const [contract, setContract] = useState(null)
  const [account, setAccount] = useState('')
  const [balance, setBalance] = useState('')
  const [betAmount, setBetAmount] = useState('0.01')
  const [choice, setChoice] = useState(true) // true = heads, false = tails
  const [isFlipping, setIsFlipping] = useState(false)
  const [stats, setStats] = useState({ wins: 0, losses: 0 })
  const [contractBalance, setContractBalance] = useState('0')
  const [entropyFee, setEntropyFee] = useState('0')
  const [recentFlips, setRecentFlips] = useState([])

  const connectWallet = async () => {
    try {
      if (window.ethereum) {
        const web3Provider = new ethers.BrowserProvider(window.ethereum)
        const accounts = await web3Provider.send('eth_requestAccounts', [])

        setProvider(web3Provider)
        const web3Signer = await web3Provider.getSigner()
        setSigner(web3Signer)
        setAccount(accounts[0])

        // Create contract instance
        const coinFlipContract = new ethers.Contract(CONTRACT_ADDRESS, COIN_FLIP_ABI, web3Signer)
        setContract(coinFlipContract)

        // Get user balance
        const userBalance = await web3Provider.getBalance(accounts[0])
        setBalance(ethers.formatEther(userBalance))

        // Get contract stats
        await updateStats(coinFlipContract, accounts[0])

        // Listen for events
        coinFlipContract.on('FlipResult', (player, sequenceNumber, result, won, payout, event) => {
          if (player.toLowerCase() === accounts[0].toLowerCase()) {
            setIsFlipping(false)
            const flip = {
              sequenceNumber: sequenceNumber.toString(),
              result: result ? 'Heads' : 'Tails',
              won,
              payout: ethers.formatEther(payout),
              timestamp: Date.now()
            }
            setRecentFlips(prev => [flip, ...prev.slice(0, 4)])
            updateStats(coinFlipContract, accounts[0])
          }
        })

      } else {
        alert('MetaMask not found! Please install MetaMask.')
      }
    } catch (error) {
      console.error('Error connecting wallet:', error)
      alert('Error connecting wallet: ' + error.message)
    }
  }

  const updateStats = async (contractInstance, userAccount) => {
    try {
      const playerStats = await contractInstance.getPlayerStats(userAccount)
      setStats({ 
        wins: Number(playerStats[0]), 
        losses: Number(playerStats[1]) 
      })

      const contractBal = await contractInstance.getContractBalance()
      setContractBalance(ethers.formatEther(contractBal))

      const fee = await contractInstance.getEntropyFee()
      setEntropyFee(ethers.formatEther(fee))

    } catch (error) {
      console.error('Error updating stats:', error)
    }
  }

  const flipCoin = async () => {
    if (!contract || !signer) {
      alert('Please connect your wallet first!')
      return
    }

    if (CONTRACT_ADDRESS === "0x0000000000000000000000000000000000000000") {
      alert('Contract not deployed yet!')
      return
    }

    try {
      setIsFlipping(true)

      // Generate a random user commitment
      const userCommitment = ethers.keccak256(ethers.toUtf8Bytes(`${Date.now()}-${Math.random()}`))

      // Calculate total amount needed (bet + entropy fee)
      const betWei = ethers.parseEther(betAmount)
      const feeWei = ethers.parseEther(entropyFee)
      const totalWei = betWei + feeWei

      const tx = await contract.flipCoin(choice, userCommitment, {
        value: totalWei
      })

      console.log('Transaction sent:', tx.hash)
      await tx.wait()
      console.log('Transaction confirmed')

      // The result will come through the event listener
    } catch (error) {
      console.error('Error flipping coin:', error)
      alert('Error flipping coin: ' + error.message)
      setIsFlipping(false)
    }
  }

  const switchToBaseSepolia = async () => {
    try {
      await window.ethereum.request({
        method: 'wallet_switchEthereumChain',
        params: [{ chainId: '0x14a34' }], // Base Sepolia chain ID
      })
    } catch (switchError) {
      // Chain not added, add it
      try {
        await window.ethereum.request({
          method: 'wallet_addEthereumChain',
          params: [{
            chainId: '0x14a34',
            chainName: 'Base Sepolia',
            nativeCurrency: {
              name: 'ETH',
              symbol: 'ETH',
              decimals: 18
            },
            rpcUrls: ['https://sepolia.base.org'],
            blockExplorerUrls: ['https://sepolia-explorer.base.org']
          }]
        })
      } catch (addError) {
        console.error('Error adding Base Sepolia network:', addError)
      }
    }
  }

  return (
    <div className="App">
      <header className="header">
        <h1>🪙 Coin Flip Game</h1>
        <p>Powered by Pyth Entropy - Provably Fair Randomness</p>
      </header>

      <main className="main">
        {!account ? (
          <div className="connect-section">
            <button onClick={switchToBaseSepolia} className="network-btn">
              Switch to Base Sepolia
            </button>
            <button onClick={connectWallet} className="connect-btn">
              Connect Wallet
            </button>
          </div>
        ) : (
          <div className="game-section">
            <div className="player-info">
              <h3>Player: {account.slice(0, 6)}...{account.slice(-4)}</h3>
              <p>Balance: {parseFloat(balance).toFixed(4)} ETH</p>
              <p>Record: {stats.wins}W - {stats.losses}L</p>
            </div>

            <div className="contract-info">
              <p>Contract Balance: {parseFloat(contractBalance).toFixed(4)} ETH</p>
              <p>Entropy Fee: {parseFloat(entropyFee).toFixed(6)} ETH</p>
            </div>

            <div className="game-controls">
              <div className="bet-input">
                <label>Bet Amount (ETH):</label>
                <input
                  type="number"
                  step="0.001"
                  min="0.001"
                  value={betAmount}
                  onChange={(e) => setBetAmount(e.target.value)}
                  disabled={isFlipping}
                />
              </div>

              <div className="choice-buttons">
                <button
                  className={`choice-btn ${choice === true ? 'selected' : ''}`}
                  onClick={() => setChoice(true)}
                  disabled={isFlipping}
                >
                  🟡 Heads
                </button>
                <button
                  className={`choice-btn ${choice === false ? 'selected' : ''}`}
                  onClick={() => setChoice(false)}
                  disabled={isFlipping}
                >
                  ⚫ Tails
                </button>
              </div>

              <button
                onClick={flipCoin}
                disabled={isFlipping}
                className="flip-btn"
              >
                {isFlipping ? '🪙 Flipping...' : '🎲 Flip Coin!'}
              </button>
            </div>

            {recentFlips.length > 0 && (
              <div className="recent-flips">
                <h3>Recent Flips</h3>
                {recentFlips.map((flip, index) => (
                  <div key={index} className={`flip-result ${flip.won ? 'win' : 'loss'}`}>
                    <span>{flip.result}</span>
                    <span>{flip.won ? '✅ Won' : '❌ Lost'}</span>
                    {flip.won && <span>+{flip.payout} ETH</span>}
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </main>
    </div>
  )
}

export default App

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  min-height: 100vh;
  color: white;
}

.App {
  max-width: 800px;
  margin: 0 auto;
  padding: 2rem;
}

.header {
  text-align: center;
  margin-bottom: 3rem;
}

.header h1 {
  font-size: 3rem;
  margin-bottom: 0.5rem;
  text-shadow: 2px 2px 4px rgba(0,0,0,0.3);
}

.header p {
  opacity: 0.9;
  font-size: 1.1rem;
}

.connect-section {
  text-align: center;
}

.network-btn, .connect-btn {
  background: rgba(255,255,255,0.2);
  border: 2px solid rgba(255,255,255,0.3);
  color: white;
  padding: 1rem 2rem;
  border-radius: 12px;
  font-size: 1.1rem;
  cursor: pointer;
  margin: 0.5rem;
  transition: all 0.3s ease;
  backdrop-filter: blur(10px);
}

.network-btn:hover, .connect-btn:hover {
  background: rgba(255,255,255,0.3);
  transform: translateY(-2px);
}

.game-section {
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

.player-info, .contract-info {
  background: rgba(255,255,255,0.1);
  padding: 1.5rem;
  border-radius: 12px;
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255,255,255,0.2);
}

.player-info h3 {
  margin-bottom: 1rem;
  color: #ffd700;
}

.game-controls {
  background: rgba(255,255,255,0.1);
  padding: 2rem;
  border-radius: 12px;
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255,255,255,0.2);
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  align-items: center;
}

.bet-input {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  align-items: center;
}

.bet-input input {
  padding: 0.75rem;
  border-radius: 8px;
  border: none;
  font-size: 1.1rem;
  width: 200px;
  text-align: center;
  background: rgba(255,255,255,0.9);
}

.choice-buttons {
  display: flex;
  gap: 1rem;
}

.choice-btn {
  background: rgba(255,255,255,0.2);
  border: 2px solid rgba(255,255,255,0.3);
  color: white;
  padding: 1rem 2rem;
  border-radius: 12px;
  font-size: 1.2rem;
  cursor: pointer;
  transition: all 0.3s ease;
  backdrop-filter: blur(10px);
}

.choice-btn:hover {
  background: rgba(255,255,255,0.3);
  transform: translateY(-2px);
}

.choice-btn.selected {
  background: rgba(255,215,0,0.3);
  border-color: #ffd700;
  color: #ffd700;
}

.flip-btn {
  background: linear-gradient(45deg, #ff6b6b, #ee5a24);
  border: none;
  color: white;
  padding: 1.5rem 3rem;
  border-radius: 16px;
  font-size: 1.3rem;
  font-weight: bold;
  cursor: pointer;
  transition: all 0.3s ease;
  box-shadow: 0 8px 16px rgba(0,0,0,0.2);
}

.flip-btn:hover:not(:disabled) {
  transform: translateY(-4px);
  box-shadow: 0 12px 24px rgba(0,0,0,0.3);
}

.flip-btn:disabled {
  opacity: 0.7;
  cursor: not-allowed;
}

.recent-flips {
  background: rgba(255,255,255,0.1);
  padding: 1.5rem;
  border-radius: 12px;
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255,255,255,0.2);
}

.recent-flips h3 {
  margin-bottom: 1rem;
  color: #ffd700;
}

.flip-result {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.75rem;
  margin: 0.5rem 0;
  border-radius: 8px;
  background: rgba(255,255,255,0.05);
}

.flip-result.win {
  border-left: 4px solid #00ff88;
}

.flip-result.loss {
  border-left: 4px solid #ff4757;
}

@media (max-width: 640px) {
  .App {
    padding: 1rem;
  }

  .header h1 {
    font-size: 2rem;
  }

  .choice-buttons {
    flex-direction: column;
    width: 100%;
  }

  .choice-btn {
    width: 100%;
  }
}

